let lastMessageInstance = null;
let writeHistory = [];

export default class Message {
    constructor(options) {
        this.options = options;
        lastMessageInstance = this;
    }

    write(msg) {
        writeHistory.push(msg);
        return true;
    }

    read() {
        return this.lastSimulatedMsg;
    }
}

export function _reset() {
    lastMessageInstance = null;
    writeHistory = [];
}

export function _getLastInstance() {
    return lastMessageInstance;
}

export function _getWriteHistory() {
    return writeHistory;
}

export function _simulateReadable(msgMap) {
    if (lastMessageInstance && lastMessageInstance.options.onReadable) {
        lastMessageInstance.lastSimulatedMsg = msgMap;
        lastMessageInstance.options.onReadable.call(lastMessageInstance);
    }
}

export function _simulateWritable() {
    if (lastMessageInstance && lastMessageInstance.options.onWritable) {
        lastMessageInstance.options.onWritable.call(lastMessageInstance);
    }
}

export function _simulateSuspend() {
    if (lastMessageInstance && lastMessageInstance.options.onSuspend) {
        lastMessageInstance.options.onSuspend.call(lastMessageInstance);
    }
}
